import sys
import math

def main():
    N = int(sys.stdin.readline())

    # Let d = x - y (positive). Then:
    # N = (x - y)(x^2 + xy + y^2)
    #   = d(3y^2 + 3dy + d^2)
    #
    # Since d^3 < N for positive y, d <= cube_root(N).
    limit = int(round(N ** (1 / 3))) + 5

    for d in range(1, limit + 1):
        if d * d * d >= N + 1:
            break
        if N % d != 0:
            continue

        m = N // d
        # Solve 3y^2 + 3dy + d^2 = m.
        # Discriminant = 12m - 3d^2.
        disc = 12 * m - 3 * d * d
        if disc < 0:
            continue

        s = math.isqrt(disc)
        if s * s != disc:
            continue

        num = s - 3 * d
        if num <= 0 or num % 6 != 0:
            continue

        y = num // 6
        x = y + d

        if y > 0 and x ** 3 - y ** 3 == N:
            print(x, y)
            return

    print(-1)

if __name__ == "__main__":
    main()
